--- ACF common message header (IEEE 1722-2025 9.4.1, Figure 62)
function M.add_acf_header(tree, tvb, off)
    tree:add(M.f.acf_msg_type, tvb(off + 0, 2))
    tree:add(M.f.acf_msg_length, tvb(off + 0, 2))
end

--- FlexRay message (IEEE 1722-2025 9.4.2, Figure 64)
function M.add_acf_flexray(tree, tvb, off)
    tree:add(M.f.acf_flexray_pad, tvb(off + 2, 1))
    tree:add(M.f.acf_flexray_mtv, tvb(off + 2, 1))
    tree:add(M.f.acf_flexray_fr_bus_id, tvb(off + 2, 1))
    tree:add(M.f.acf_flexray_chan, tvb(off + 3, 1))
    tree:add(M.f.acf_flexray_str, tvb(off + 3, 1))
    tree:add(M.f.acf_flexray_syn, tvb(off + 3, 1))
    tree:add(M.f.acf_flexray_pre, tvb(off + 3, 1))
    tree:add(M.f.acf_flexray_nfi, tvb(off + 3, 1))
    tree:add(M.f.acf_flexray_message_timestamp, tvb(off + 4, 8))
    tree:add(M.f.acf_flexray_fr_frame_id, tvb(off + 12, 4))
    tree:add(M.f.acf_flexray_cycle, tvb(off + 12, 4))
end

--- CAN/CAN FD message (IEEE 1722-2025 9.4.3, Figure 65)
